+import {jest} from '@jest/globals';
+import {ToolRegistry} from './registry.js';
+
+describe('ToolRegistry', () => {
+  it('throws at registration naming a static tool whose input schema cannot compile', () => {
+    const registry = new ToolRegistry();
+
+    expect(() =>
+      registry.register(
+        {
+          name: 'broken_weather',
+          description: 'Broken weather tool',
+          inputSchema: {type: 'not-a-json-schema-type'},
+        },
+        async () => 'unreachable'
+      )
+    ).toThrow(/broken_weather/);
+  });
+
+  it('returns a required-property rejection without calling the executor', async () => {
+    const registry = new ToolRegistry();
+    const execute = jest.fn(async () => 'sunny');
+    registry.register(
+      {
+        name: 'get_weather',
+        description: 'Get weather for a location',
+        inputSchema: {
+          type: 'object',
+          properties: {location: {type: 'string'}},
+          required: ['location'],
+        },
+      },
+      execute
+    );
+
+    const response = await registry.execute('get_weather', {});
+
+    expect({result: response.result, executorCalls: execute.mock.calls.length}).toEqual({
+      result: expect.stringMatching(/location.*required|required.*location/i),
+      executorCalls: 0,
+    });
+  });
+});

